import{_ as t,a as o,o as n,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Social Login","description":"","frontmatter":{"outline":false,"examples":[{"id":"social-login-google","title":"Social Login with Google","description":"Sign in (or sign up) with a Google ID token from Google Identity Services (web) or the Google SDK (mobile).","query":"mutation createSocialLogin(\\n  $provider: String!\\n  $idToken: String\\n) {\\n  createSocialLogin(\\n    input: {\\n      provider: $provider\\n      idToken: $idToken\\n    }\\n  ) {\\n    socialLogin {\\n      id\\n      _id\\n      token\\n      apiToken\\n      firstName\\n      lastName\\n      email\\n      phone\\n      isNewCustomer\\n      success\\n      message\\n      code\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"provider\\": \\"google\\",\\n  \\"idToken\\": \\"eyJhbGciOiJSUzI1NiIsImtpZCI6…\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createSocialLogin\\": {\\n      \\"socialLogin\\": {\\n        \\"id\\": \\"1782\\",\\n        \\"_id\\": 1782,\\n        \\"token\\": \\"1550|1LMsQ6hVh0mZ8b0c2Jit4uVWAShoK8TfeOxnjEmG\\",\\n        \\"apiToken\\": \\"rjTLsuOsX5qehio2q1cMeMd6TCaIKofwQ4mb7y2zcy0\\",\\n        \\"firstName\\": \\"Nadia\\",\\n        \\"lastName\\": \\"Rahman\\",\\n        \\"email\\": \\"nadia@example.com\\",\\n        \\"phone\\": null,\\n        \\"isNewCustomer\\": true,\\n        \\"success\\": true,\\n        \\"message\\": \\"Signed in successfully.\\",\\n        \\"code\\": null\\n      }\\n    }\\n  }\\n}\\n"},{"id":"social-login-facebook","title":"Social Login with Facebook","description":"Sign in with a Facebook access token from the Facebook Login SDK.","query":"mutation createSocialLogin(\\n  $provider: String!\\n  $accessToken: String\\n) {\\n  createSocialLogin(\\n    input: {\\n      provider: $provider\\n      accessToken: $accessToken\\n    }\\n  ) {\\n    socialLogin {\\n      id\\n      _id\\n      token\\n      apiToken\\n      firstName\\n      lastName\\n      email\\n      phone\\n      isNewCustomer\\n      success\\n      message\\n      code\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"provider\\": \\"facebook\\",\\n  \\"accessToken\\": \\"EAAJZC…\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createSocialLogin\\": {\\n      \\"socialLogin\\": {\\n        \\"id\\": \\"1783\\",\\n        \\"_id\\": 1783,\\n        \\"token\\": \\"1551|8b0c2Jit4uVWAShoK8TfeOxnjEmG1LMsQ6hVh0mZ\\",\\n        \\"apiToken\\": \\"q1cMeMd6TCaIKofwQ4mb7y2zcy0rjTLsuOsX5qehio2\\",\\n        \\"firstName\\": \\"Omar\\",\\n        \\"lastName\\": \\"Ali\\",\\n        \\"email\\": \\"omar@example.com\\",\\n        \\"phone\\": null,\\n        \\"isNewCustomer\\": false,\\n        \\"success\\": true,\\n        \\"message\\": \\"Signed in successfully.\\",\\n        \\"code\\": null\\n      }\\n    }\\n  }\\n}\\n"},{"id":"social-login-linkedin","title":"Social Login with LinkedIn","description":"Sign in with a LinkedIn access token.","query":"mutation createSocialLogin(\\n  $provider: String!\\n  $accessToken: String\\n) {\\n  createSocialLogin(\\n    input: {\\n      provider: $provider\\n      accessToken: $accessToken\\n    }\\n  ) {\\n    socialLogin {\\n      id\\n      _id\\n      token\\n      apiToken\\n      firstName\\n      lastName\\n      email\\n      phone\\n      isNewCustomer\\n      success\\n      message\\n      code\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"provider\\": \\"linkedin\\",\\n  \\"accessToken\\": \\"AQV8…\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createSocialLogin\\": {\\n      \\"socialLogin\\": {\\n        \\"id\\": \\"1784\\",\\n        \\"_id\\": 1784,\\n        \\"token\\": \\"1552|4uVWAShoK8TfeOxnjEmG1LMsQ6hVh0mZ8b0c2Jit\\",\\n        \\"apiToken\\": \\"TCaIKofwQ4mb7y2zcy0rjTLsuOsX5qehio2q1cMeMd6\\",\\n        \\"firstName\\": \\"Chen\\",\\n        \\"lastName\\": \\"Wei\\",\\n        \\"email\\": \\"chen@example.com\\",\\n        \\"phone\\": null,\\n        \\"isNewCustomer\\": true,\\n        \\"success\\": true,\\n        \\"message\\": \\"Signed in successfully.\\",\\n        \\"code\\": null\\n      }\\n    }\\n  }\\n}\\n"},{"id":"social-login-invalid","title":"Invalid Token","description":"The provider rejected the token. Obtain a fresh one and retry.","query":"mutation createSocialLogin(\\n  $provider: String!\\n  $idToken: String\\n) {\\n  createSocialLogin(\\n    input: {\\n      provider: $provider\\n      idToken: $idToken\\n    }\\n  ) {\\n    socialLogin {\\n      success\\n      message\\n      code\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"provider\\": \\"google\\",\\n  \\"idToken\\": \\"expired-or-tampered-token\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createSocialLogin\\": {\\n      \\"socialLogin\\": {\\n        \\"success\\": false,\\n        \\"message\\": \\"The social login token is invalid or expired. Please try again.\\",\\n        \\"code\\": \\"SOCIAL_TOKEN_INVALID\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/shop/mutations/social-login.md","filePath":"api/graphql-api/shop/mutations/social-login.md","lastUpdated":1787725411000}'),i={name:"api/graphql-api/shop/mutations/social-login.md"};function a(r,e,s,c,l,h){return n(),o("div",null,e[0]||(e[0]=[d('<h1 id="social-login" tabindex="-1">Social Login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social Login&quot;">​</a></h1><p>Sign a customer in — or sign them up on first sight — with a token their app or browser already holds. The client obtains the token from the provider itself (Google Identity Services or the Google SDK, the Facebook Login SDK, or LinkedIn), so there is no browser redirect; the token is verified server-side and a Bearer <code>token</code> is returned, the same credential <a href="/api/graphql-api/shop/mutations/customer-login.html">Customer Login</a> answers with.</p><p>One mutation both signs in and signs up, so the app never has to check first whether the email exists:</p><ul><li>A known provider account signs in.</li><li>A known email links the provider to that account and signs in.</li><li>Neither creates the account, links it, and signs in — <code>isNewCustomer</code> is <code>true</code>.</li></ul><p>Accounts created this way have no password; a customer who wants one uses the forgot-password flow.</p><h2 id="supported-providers" tabindex="-1">Supported Providers <a class="header-anchor" href="#supported-providers" aria-label="Permalink to &quot;Supported Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>provider</code></th><th>Token argument</th><th>Where the client gets it</th></tr></thead><tbody><tr><td><code>google</code></td><td><code>idToken</code> (preferred) or <code>accessToken</code></td><td>Google Identity Services (web) or the Google SDK (mobile)</td></tr><tr><td><code>facebook</code></td><td><code>accessToken</code></td><td>Facebook Login SDK (web or mobile)</td></tr><tr><td><code>linkedin</code></td><td><code>accessToken</code></td><td>LinkedIn OAuth</td></tr></tbody></table><p>A provider must be enabled and configured under <strong>Configure → Customer → Settings → Social Login</strong> in the admin panel. No Bearer token is needed to call this mutation — the storefront key alone authorizes it.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>provider</code></td><td>String</td><td>✅ Yes</td><td>One of <code>google</code>, <code>facebook</code>, <code>linkedin</code>.</td></tr><tr><td><code>idToken</code></td><td>String</td><td>Conditional</td><td>Google ID token. Use for <code>google</code>.</td></tr><tr><td><code>accessToken</code></td><td>String</td><td>Conditional</td><td>OAuth access token. Use for <code>facebook</code> and <code>linkedin</code>, or for <code>google</code> when you hold an access token instead of an ID token.</td></tr><tr><td><code>deviceToken</code></td><td>String</td><td>❌ No</td><td>FCM device token to register push in the same call. Applies only when the Bagisto Push Notification package is installed.</td></tr></tbody></table><p>Send <code>idToken</code> for Google, or <code>accessToken</code> for Facebook and LinkedIn — one token is enough.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code> / <code>_id</code></td><td>ID / Int</td><td>Customer ID.</td></tr><tr><td><code>token</code></td><td>String</td><td><strong>The authentication credential</strong> (format <code>&lt;id&gt;|&lt;secret&gt;</code>). Send as <code>Authorization: Bearer &lt;token&gt;</code>.</td></tr><tr><td><code>apiToken</code></td><td>String</td><td>Legacy field, kept for backward compatibility. <strong>Not</strong> an auth Bearer.</td></tr><tr><td><code>firstName</code></td><td>String</td><td>Customer first name.</td></tr><tr><td><code>lastName</code></td><td>String</td><td>Customer last name.</td></tr><tr><td><code>email</code></td><td>String</td><td>Customer email.</td></tr><tr><td><code>phone</code></td><td>String</td><td>Customer phone, or <code>null</code> if unset.</td></tr><tr><td><code>isNewCustomer</code></td><td>Boolean</td><td><code>true</code> when the mutation created the account, <code>false</code> when it signed an existing one in.</td></tr><tr><td><code>success</code></td><td>Boolean</td><td>Whether sign-in succeeded.</td></tr><tr><td><code>message</code></td><td>String</td><td>Human-readable result.</td></tr><tr><td><code>code</code></td><td>String</td><td>A stable machine-readable error code on failure, <code>null</code> on success.</td></tr></tbody></table><h2 id="error-codes" tabindex="-1">Error Codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error Codes&quot;">​</a></h2><p>Every failure returns <code>success: false</code>, a translated <code>message</code>, and a stable <code>code</code>.</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>SOCIAL_TOKEN_REQUIRED</code></td><td>No <code>idToken</code> / <code>accessToken</code> was sent.</td></tr><tr><td><code>SOCIAL_TOKEN_INVALID</code></td><td>The provider rejected the token — obtain a fresh one and retry.</td></tr><tr><td><code>SOCIAL_TOKEN_AUDIENCE</code></td><td>The Google token was issued for a different app. A configuration mismatch, not retryable.</td></tr><tr><td><code>SOCIAL_EMAIL_REQUIRED</code></td><td>The provider shared no email address. Use email sign-up instead.</td></tr><tr><td><code>ACCOUNT_INACTIVE</code></td><td>The matched account is not activated.</td></tr><tr><td><code>PROVIDER_NOT_SUPPORTED</code></td><td>The <code>provider</code> value is not one of the supported providers.</td></tr><tr><td><code>PROVIDER_DISABLED</code></td><td>The provider is not enabled in the admin panel.</td></tr></tbody></table><h2 id="token-usage" tabindex="-1">Token Usage <a class="header-anchor" href="#token-usage" aria-label="Permalink to &quot;Token Usage&quot;">​</a></h2><p>Once signed in, send the <code>token</code> in the <code>Authorization</code> header on authenticated requests:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Authorization&quot;: &quot;Bearer 1550|1LMsQ6hVh0mZ8b0c2Jit4uVWAShoK8TfeOxnjEmG&quot;</span></span></code></pre></div>',19)]))}const u=t(i,[["render",a]]);export{p as __pageData,u as default};
